        private static readonly Dictionary<string, Geometry> GeometryCache =
            new Dictionary<string, Geometry>(StringComparer.Ordinal);

        /// <summary>取官方 SVG 路径原文；未知名称直接抛异常（图标名是内部常量，拼错应当立刻暴露）。</summary>
        public static string PathData(string name)
        {
            if (name == null) throw new ArgumentNullException(nameof(name));
            string data;
            if (!Paths.TryGetValue(name, out data))
                throw new ArgumentOutOfRangeException(nameof(name), name, "未收录的 Material Symbols 图标。");
            return data;
        }

        /// <summary>取 WPF 几何（已冻结，可跨线程使用）。</summary>
        public static Geometry GetGeometry(string name)
        {
            lock (GeometryCache)
            {
                Geometry geometry;
                if (GeometryCache.TryGetValue(name, out geometry)) return geometry;

                geometry = System.Windows.Media.Geometry.Parse(PathData(name));
                geometry.Freeze();
                GeometryCache[name] = geometry;
                return geometry;
            }
        }

        /// <summary>
        /// 建一个单色图标控件（用 Foreground 着色，随按钮悬停/禁用自动换色）。
        /// 用矢量路径而不是字体或图片：在任何 DPI 下都清晰，也不需要随程序集分发字体文件。
        /// </summary>
        public static System.Windows.FrameworkElement CreateIcon(string name, double size)
        {
            return new MaterialIcon
            {
                Symbol = name,
                Width = size,
                Height = size,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };
        }
    }
